/** Strip code fences, then return the first balanced {...} span that parses. */
export function extractReturnObject(text) {
  if (typeof text !== 'string' || !text.length) return { ok: false, reason: 'empty_output', value: null }
  const stripped = text.replace(/```[a-zA-Z]*\n?/g, '').replace(/```/g, '')
  for (let start = stripped.indexOf('{'); start !== -1; start = stripped.indexOf('{', start + 1)) {
    let depth = 0
    let inString = false
    let escaped = false
    for (let i = start; i < stripped.length; i += 1) {
      const ch = stripped[i]
      if (inString) {
        if (escaped) escaped = false
        else if (ch === '\\') escaped = true
        else if (ch === '"') inString = false
        continue
      }
      if (ch === '"') inString = true
      else if (ch === '{') depth += 1
      else if (ch === '}') {
        depth -= 1
        if (depth === 0) {
          const span = stripped.slice(start, i + 1)
          try {
            const value = JSON.parse(span)
            if (value && typeof value === 'object' && !Array.isArray(value)) {
              return {
                ok: true,
                reason: null,
                value,
                span,
                span_start: start,
                span_end: i + 1,
                stripped,
                span_bytes: Buffer.byteLength(span),
              }
            }
          } catch {
            /* keep scanning */
          }
          break
        }
      }
    }
  }
  return { ok: false, reason: 'no_parsable_return_object', value: null }
}

