/**
 * The part of a report that speaks in the report's own voice: everything
 * outside the return object, plus every field of the return object except the
 * quotation fields inside findings[].
 */
export function assertiveSurface(text, parsed) {
  const raw = typeof text === 'string' ? text : ''
  if (!parsed || !parsed.ok) return raw
  const outside =
    typeof parsed.stripped === 'string' && typeof parsed.span_start === 'number'
      ? parsed.stripped.slice(0, parsed.span_start) + ' ' + parsed.stripped.slice(parsed.span_end)
      : ''
  const v = parsed.value
  const findings = Array.isArray(v.findings) ? v.findings : []
  const assertedFindings = findings.map((f) => {
    if (!f || typeof f !== 'object') return f
    const copy = { ...f }
    for (const k of QUOTATION_FIELDS) delete copy[k]
    return copy
  })
  const asserted = { ...v, findings: assertedFindings }
  return `${outside}\n${JSON.stringify(asserted)}`
}

