export function parseJsonBlock(text) {
  const s = String(text)
  const i = s.indexOf('{')
  if (i < 0) return null
  try { return JSON.parse(s.slice(i)) } catch { /* fall through */ }
  // Tolerate a trailing hint line after the JSON object.
  let depth = 0
  for (let j = i; j < s.length; j++) {
    if (s[j] === '{') depth++
    else if (s[j] === '}') { depth--; if (depth === 0) { try { return JSON.parse(s.slice(i, j + 1)) } catch { return null } } }
  }
  return null
}

