/** NORMALISATION token rule, applied verbatim. */
export function normaliseToken(value) {
  if (typeof value !== 'string') return ABSENT
  let t = value.normalize('NFKC').toLowerCase().trim()
  t = t.replace(/^[`*_"'\s]+/, '').replace(/[`*_"'\s]+$/, '')
  t = t.replace(/[\s\-_]+/g, '_')
  t = t.replace(/^_+|_+$/g, '')
  return t.length ? t : ABSENT
}

