/** Collapse a ranked identifier list to one entry per identifier, keeping the best (lowest) rank. */
export function dedupeRanked(entries) {
  const byId = new Map()
  let duplicates = 0
  for (let i = 0; i < entries.length; i++) {
    const e = entries[i]
    const id = e.id
    if (byId.has(id)) { duplicates++; continue } // first occurrence is the best rank; later ones are dropped
    byId.set(id, { ...e, rank: byId.size + 1 })
  }
  return { ranked: [...byId.values()], duplicates }
}

