// Per-arm usage-category extraction.
//
// The four categories (input, output, cache read, cache write) are read from
// the arm's OWN returned receipt using alias lists that were read from each
// runtime's source, not guessed. A category the arm does not return is null.
// Nothing is estimated, summed, derived from a total, or back-filled.
import { USAGE_CATEGORY_MAP } from './constants.mjs'

const CATEGORIES = USAGE_CATEGORY_MAP.categories

function asCount(v) {
  if (typeof v === 'number' && Number.isFinite(v) && v >= 0) return v
  return null
}

/** Walk the arm's declared nested locators, e.g. Codex ThreadTokenUsage.total. */
function candidateObjects(raw, armSpec) {
  const out = []
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) out.push({ at: '', obj: raw })
  for (const key of armSpec.nested_locators || []) {
    const nested = raw && typeof raw === 'object' ? raw[key] : null
    if (nested && typeof nested === 'object' && !Array.isArray(nested)) out.push({ at: key, obj: nested })
  }
  return out
}

/**
 * @param {string} arm  'A' | 'B' | 'C'
 * @param {unknown} raw the arm's own usage object, exactly as its receipt carried it
 * @returns {{usage: Record<string, number|null>, provenance: object}}
 */
export function parseUsage(arm, raw) {
  const armSpec = USAGE_CATEGORY_MAP.arms[arm]
  if (!armSpec) throw new Error(`no usage category map for arm ${arm}`)

  const usage = Object.fromEntries(CATEGORIES.map((c) => [c, null]))
  const provenance = {
    arm,
    runtime: armSpec.runtime,
    receipt_locator: armSpec.receipt_locator,
    missing_policy: USAGE_CATEGORY_MAP.missing_policy,
    resolved: {},
    raw_present: raw !== null && raw !== undefined,
    raw_keys: raw && typeof raw === 'object' && !Array.isArray(raw) ? Object.keys(raw).sort() : [],
  }

  if (!provenance.raw_present) {
    for (const c of CATEGORIES) provenance.resolved[c] = { value: null, source_key: null, reason: 'no_usage_object' }
    return { usage, provenance }
  }

