/**
 * USAGE_COMPLETENESS, applied. The denominator is structurally the replay
 * indices; passing a cancel index here is a programming error, not a score.
 */
export function usageCompleteness(perSubmission) {
  const replay = new Set(REPLAY_INDICES)
  for (const s of perSubmission) {
    if (!replay.has(s.index)) {
      throw new Error(
        `usageCompleteness received submission index ${s.index}, which is exempt by ` +
          `USAGE_COMPLETENESS (${JSON.stringify(USAGE_COMPLETENESS.exempt_indices)}). ` +
          'Scoring an interrupted turn for usage completeness is the v1 contradiction this resolves.',
      )
    }
  }
  const cats = USAGE_COMPLETENESS.threshold_categories
  let complete = 0
  const detail = []
  for (const s of perSubmission) {
    const u = s.usage || {}
    const missing = cats.filter((c) => u[c] === null || u[c] === undefined)
    const ok = missing.length === 0 && s.status !== 'blocked'
    if (ok) complete += 1
    detail.push({ index: s.index, status: s.status, complete: ok, missing })
  }
  const denominator = USAGE_COMPLETENESS.denominator
  return {
    numerator: complete,
    denominator,
    rate: denominator === 0 ? null : complete / denominator,
    scored_over: USAGE_COMPLETENESS.scored_over,
    exempt_indices: USAGE_COMPLETENESS.exempt_indices,
    detail,
  }
}

