/**
 * leakage: over every query issued in both scope passes, count each returned hit whose derived
 * scope differs from the scope the query was issued in. A hit whose ref cannot be derived is
 * counted into `unresolved_refs`, NOT into leakage.
 */
export function leakage (records, k) {
  let leaks = 0
  let unresolvedRefs = 0
  let inspected = 0
  const detail = []
  for (const rec of records) {
    if (!rec.scope) continue
    for (const h of (rec.hits || []).slice(0, k)) {
      inspected += 1
      const ref = hitRef(h)
      if (!ref) { unresolvedRefs += 1; continue }
      if (ref.scope !== rec.scope) {
        leaks += 1
        detail.push({ case_id: rec.case_id, query_scope: rec.scope, hit_scope: ref.scope })
      }
    }
  }
  return { leaks, inspected, unresolved_refs: unresolvedRefs, detail }
}

