/**
 * recall@k: a case counts once if ANY of its expected spans (union over both authors, see
 * cases.mjs) overlaps by at least one line with the span of ANY of the arm's top-k hits,
 * with normalized-path equality. Exact integer count over answerable cases that have at least
 * one parseable expected span.
 */
export function recallAtK (cases, byCase, k) {
  let hits = 0
  let scorable = 0
  let unresolvedRefs = 0
  const detail = []
  for (const c of cases) {
    if (c.no_answer || !c.spans.length) continue
    scorable += 1
    const rec = byCase.get(c.case_id)
    const top = (rec?.hits || []).slice(0, k)
    let ok = false
    for (const h of top) {
      const ref = hitRef(h)
      if (!ref) { unresolvedRefs += 1; continue }
      if (c.spans.some((s) => spansOverlap(s, ref))) { ok = true; break }
    }
    if (ok) hits += 1
    detail.push({ case_id: c.case_id, hit: ok, returned: top.length })
  }
  return { hits, scorable, unresolved_refs: unresolvedRefs, detail }
}

