/** Nearest-rank p95: the ceil(0.95 * n)-th value in ascending order — always an observed sample. */
export function p95NearestRank (samples) {
  const xs = samples.filter((x) => Number.isFinite(x)).slice().sort((a, b) => a - b)
  if (!xs.length) return null
  const idx = Math.ceil(0.95 * xs.length)
  return xs[Math.min(idx, xs.length) - 1]
}

