/** Nearest-rank percentile: the ceil(p*n)-th value of the ascending sort, 1-based.
 *  For n = 20 and p = 0.95 this is the 19th of 20. */
export function nearestRankPercentile(values, p) {
  if (!values.length) return null
  const v = [...values].sort((a, b) => a - b)
  const idx = Math.max(1, Math.ceil(p * v.length))
  return v[idx - 1]
}

